import argparse
import ast
import hashlib
import json
import struct
import subprocess
import zipfile

sys.dont_write_bytecode = True
sys.path.insert(0, str(CASE))
from scene_common import CASES, REPO, SUITE_KEY, load_physics, parameters, spring_properties, vocabulary_module
from pcve_media_contract import require_times, require_video

TOOLS = CASE / "tools"
BLENDER = REPO / "tools/blender-4.3.2-linux-x64/blender"
if not BLENDER.is_file():
    from pcve_assets import blender as _blender
    BLENDER = _blender()
VENV_PYTHON = REPO / ".venv-rigid-elastic/bin/python"


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def repo_path(value):
    value = Path(value)
    return value if value.is_absolute() else REPO / value


def catalog_id(case):
    return "source" if case == "source" else PCVE_EDITS[case]["catalog_case_id"]


def load_times(path):
    """The 'time' array of a states.npz without numpy (the system python3 has none)."""
    with zipfile.ZipFile(path) as z:
        raw = z.read("time.npy")
    size, = struct.unpack_from("<H", raw, 8)
    header = ast.literal_eval(raw[10:10 + size].decode("latin1").strip())
    code = {"<f8": "d", "<f4": "f"}[header["descr"]]
    return struct.unpack(f"<{header['shape'][0]}{code}", raw[10 + size:])


def check_catalog():
    """The literal catalog above must equal what edit_vocab.py derives."""
    vocab = vocabulary_module()
    dsl = vocab.dsl
    if list(dsl.editable_objects(vocab.VOCAB)) != PCVE_SOURCE["editable_objects"]:
        raise RuntimeError("editable_objects differ from edit_vocab.py")
    if list(PCVE_EDITS) != [case for case in CASES if case != "source"]:
        raise RuntimeError("catalog cases differ from scene_common.CASES")
    for case, item in PCVE_EDITS.items():
        command = CASES[case][1]
        edit = dsl.parse(command, vocab.VOCAB)
        override = dsl.to_physics_override(edit, vocab.VOCAB)
        diff = {key: {"from": vocab.VOCAB.baseline_physics[key], "to": value} for key, value in override.items()}
        # ADD: native_edit_dsl is the native preset DSL (CASES), edit_dsl the published BETWEEN form.
        native_command = item.get("native_edit_dsl", item["edit_dsl"])
        published = vocab.ADD_LINE_DSL if isinstance(edit, dsl.AddEdit) else command
        if native_command != command or item["edit_dsl"] != published or item["physics_override"] != override or item["physics_diff"] != diff:
            raise RuntimeError(f"{case}: catalog DSL/override differs from edit_vocab.py")
        if item["prompts"] != vocab.case_prompts(command):
            raise RuntimeError(f"{case}: catalog prompts differ from the DSL rendering")
        resolved, _ = parameters(case)
        for key, value in override.items():
            if resolved[key] != value:
                raise RuntimeError(f"{case}: {key} does not resolve to the native case value")


def verify(suite, selection):
    """Published suite + the native states it shows, read from their current locations."""
    check_catalog()
    manifest = read(CASE / "scene_manifest.json")
    pointer = manifest["canonical_suites"][SUITE_KEY]
    if (REPO / pointer["target"]).resolve() != suite.resolve():
        print(f"note: verifying {suite}, which is not the canonical target {pointer['target']}", file=sys.stderr)
    native = manifest["native_outputs"]
    states_root, audits, renders = (repo_path(native[k]) for k in ("state_root", "audit_root", "render_root"))
    suite_manifest = read(suite / "suite_manifest.json")
    rows_by_id = {row["case_id"]: row for row in [suite_manifest["source"], *suite_manifest["edits"]]}
    rows = []
    for case in selection:
        cid = catalog_id(case)
        target = suite / "cases" / cid
        row = rows_by_id[cid]
        video_hash = sha(target / "video.mp4")
        if not (video_hash == pointer["case_video_sha256"][case] == row["video_sha256"] == read(target / "provenance.json")["video_sha256"]):
            raise RuntimeError(f"{case}: video bytes differ from scene_manifest/suite_manifest/provenance")
        media = require_video(target / "video.mp4")
        prompts = read(target / "prompts.json")
        expected = PCVE_SOURCE if case == "source" else PCVE_EDITS[case]
        if prompts["prompts"] != expected["prompts"] or prompts["edit_dsl"] != expected["edit_dsl"]:
            raise RuntimeError(f"{case}: prompts.json differs from the builder catalog")
        state_dir = states_root / case
        states_hash = sha(state_dir / "states.npz")
        if states_hash != manifest["case_state_sha256"][case]:
            raise RuntimeError(f"{case}: registered native states changed")
        require_times(load_times(state_dir / "states.npz"))
        resolved, _ = parameters(case)
        if load_physics(state_dir / "resolved_physics.json") != dict(resolved, spring_derived=spring_properties(resolved)):
            raise RuntimeError(f"{case}: resolved_physics.json differs from scene_common.parameters()")
        audit = read(audits / case / "physics_audit.json")
        if audit["case_id"] != case:
            raise RuntimeError(f"{case}: physics audit belongs to another case")
        gt = read(target / "ground_truth_transforms.json")
        if gt.get("format_version") != "pcve_ground_truth/1" or len(gt["frames"]) != media["frames"]:
            raise RuntimeError(f"{case}: ground truth is not the pcve_ground_truth/1 record of the video")
        require_times([frame["time_sec"] for frame in gt["frames"]])
        render = repo_path(native["render_root"]) / native.get("render_case_dir", "{case}").format(case=case)
        record = read(render / native.get("render_record", "render_report.json"))
        if record.get("states_sha256") != states_hash:
            raise RuntimeError(f"{case}: the video was rendered from other native states")
        rows.append({"case": case, "catalog_case_id": cid, "video_sha256": video_hash, "states_sha256": states_hash, "media": media})
    print(json.dumps({"suite": str(suite), "verified_cases": rows, "status": "VERIFIED"},
                     indent=2, ensure_ascii=False))


def compare_resim(rerun, selection):
    """A fresh solve (simulate entry --out DIR) against the registered states."""
    subprocess.run([str(VENV_PYTHON), "-B", str(TOOLS / "compare_states.py"), "--rerun", str(rerun), "--cases", *selection], check=True)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--stage", choices=("verify", "prompts", "validate-physics", "compare-resim", "encode", "publish"),
                        default="verify")
    parser.add_argument("--cases", nargs="+", choices=list(CASES), default=list(CASES))
    parser.add_argument("--suite-root", type=Path, help="suite folder; verify reads the published suite (canonical target in scene_manifest.json) by default, prompts and publish write to renders/spring_block_step/suite_build/<suite> by default")
    parser.add_argument("--rerun", type=Path, help="compare-resim: output folder of a fresh simulate run (<DIR>/cases/<case>/states.npz)")
    parser.add_argument("--blender-bin", type=Path, default=BLENDER, help="publish stage (ground truth of the new suite)")
    args = parser.parse_args()
    suite = args.suite_root or REPO / read(CASE / "scene_manifest.json")["canonical_suites"][SUITE_KEY]["target"]
    build_suite = args.suite_root or REPO / "renders" / PCVE_SCENE / "suite_build" / SUITE_KEY
    tool = [sys.executable, "-B", str(TOOLS / "publish_suite.py")]
    scripts = (REPO / "scripts").resolve()
    if suite.resolve() == scripts or scripts in suite.resolve().parents:
        parser.error("the suite lives under renders/, not scripts/")
    if args.stage == "verify":
        verify(suite, args.cases)
    elif args.stage == "prompts":
        check_catalog()
        subprocess.run([*tool, "prompts", "--suite", str(build_suite)], check=True)
    elif args.stage == "validate-physics":
        subprocess.run([str(VENV_PYTHON), "-B", str(TOOLS / "validate_physics.py")], check=True)
    elif args.stage == "compare-resim":
        if not args.rerun:
            parser.error("--rerun <output folder of the simulate entry> is required")
        compare_resim(args.rerun, args.cases)
    elif args.stage == "encode":
        subprocess.run([*tool, "encode", "--cases", *args.cases], check=True)
    else:
        check_catalog()
        subprocess.run([*tool, "build", "--suite", str(build_suite), "--blender", str(args.blender_bin)], check=True)
        verify(build_suite, list(CASES))
